namespace sv_fc8ef959310445abb01aadbb549dbd44.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Brown",
        "Dr. Davis"
    ];

    private static readonly List<string> AllTimeSlots =
    [
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "11:30 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM",
        "3:30 PM",
        "4:00 PM"
    ];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        // Stub: return all slots for any valid doctor/date combination
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    /// <summary>
    /// Validates the full appointment request against server-side business rules.
    /// Returns a dictionary of field name → error message for any violations.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Simulate outstanding balance for a specific email
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = "Account has outstanding balance";
        }

        // Simulate doctor not accepting self-pay
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.PreferredDoctor)] =
                "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on a specific time slot
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(AppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_fc8ef959310445abb01aadbb549dbd44.Services;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select an insurance provider.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string PreferredDoctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a date.")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string ReasonForVisit { get; set; } = string.Empty;

    public bool IsDateInFuture =>
        AppointmentDate.HasValue && AppointmentDate.Value.Date > DateTime.Today;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_fc8ef959310445abb01aadbb549dbd44.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="model.PreferredDoctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.PreferredDoctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
                @if (model.AppointmentDate.HasValue && !model.IsDateInFuture)
                {
                    <div class="text-danger">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3"
                               @bind-Value="model.ReasonForVisit" />
                <ValidationMessage For="() => model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability"
                        disabled="@isChecking">
                    @(isChecking ? "Checking…" : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@model.PatientName</strong>
        with <strong>@model.PreferredDoctor</strong>
        on @model.AppointmentDate?.ToString("MMMM d, yyyy") at @model.TimeSlot.
    </div>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore serverMessageStore = default!;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool submitted;

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        serverMessageStore = new ValidationMessageStore(editContext);

        // Clear server errors when user edits any field
        editContext.OnFieldChanged += (_, args) =>
        {
            serverMessageStore.Clear(args.FieldIdentifier);
            availabilityConfirmed = false;
        };

        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        editContext.Validate();

        var hasStep1Errors = Step1Fields
            .Select(f => new FieldIdentifier(model, f))
            .Any(fi => editContext.GetValidationMessages(fi).Any());

        if (!hasStep1Errors)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDateChanged()
    {
        availabilityConfirmed = false;
        timeSlots = [];
        model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(model.PreferredDoctor)
            && model.AppointmentDate.HasValue
            && model.IsDateInFuture)
        {
            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                model.PreferredDoctor, model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverMessageStore.Clear();
        availabilityConfirmed = false;

        // Run full validation first
        editContext.Validate();

        bool step2Valid = !editContext.GetValidationMessages().Any();

        if (!model.IsDateInFuture)
        {
            step2Valid = false;
        }

        if (!step2Valid)
        {
            return;
        }

        isChecking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                model.Email,
                model.InsuranceProvider,
                model.PreferredDoctor,
                model.TimeSlot);

            if (errors.Count > 0)
            {
                foreach (var (field, message) in errors)
                {
                    serverMessageStore.Add(new FieldIdentifier(model, field), message);
                }
                editContext.NotifyValidationStateChanged();
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed && model.IsDateInFuture)
        {
            submitted = true;
        }
    }
}

